import hashlib
import json
from pathlib import Path
import re

A=Path(__file__).resolve().parent
ROOT=A.parents[3]
def sha(p): return hashlib.sha256(p.read_bytes()).hexdigest()
def rel(p): return p.relative_to(ROOT).as_posix()
raw=(ROOT/'course/chapters/13.md').read_bytes()
headers=list(re.finditer(rb'(?m)^## [^\r\n]+',raw))
i=next(i for i,h in enumerate(headers) if h[0].startswith(b'## 13.10 '))
section=raw[headers[i].start():headers[i+1].start() if i+1<len(headers) else len(raw)]
assert section==(A/'inputs/section-13.10.md').read_bytes()
source_sha=hashlib.sha256(section).hexdigest()
cpu=json.loads((A/'execution/cpu-results.json').read_text())
env=json.loads((A/'execution/environment.json').read_text())
render=json.loads((A/'render/render-result.json').read_text())
assert render['exit_code']==0 and not render['timed_out']
assert cpu['original_fence_exit_code']==0
artifacts=[]
def artifact(id,file,kind,description,**kw):
    p=A/file
    artifacts.append(dict(id=id,path=rel(p),sha256=sha(p),kind=kind,description=description,**kw))
