def ev(source,locator,supports):return dict(source_id=source,locator=locator,supports=supports)
claims=[]
def claim(id,kind,statement,location,scope,evidence,artifact_ids,verification=None):
    c=dict(id=id,kind=kind,statement=statement,location=location,scope=scope,status='verified',evidence=evidence,artifact_ids=artifact_ids)
    if verification is not None:c['verification']=verification
    claims.append(c)
def verification(expected,observed,details,**kw):return dict(method='executed',expected=expected,observed=observed,details=details,**kw)

